package day1;

public class Program3_ArithmaticOperator {

	public static void main(String[] args) {
		// TODO Auto-generated method stub
		int a=10;
		int b=20;
		System.out.println(a+b);
		System.out.println(b-a);
		System.out.println(b*a);
		System.out.println(b/a);
		System.out.println(b%a);
	}

}
